do $$
declare b text := 'voz-y-rumbo'; s bigint; it bigint; d date;
begin
  if not exists (select 1 from businesses where id = b and is_demo and category_id = 'NEG-EDU') or exists (select 1 from items where business_id = b and module = 'svc' and removed_at is null) then return; end if;
  update businesses set modules_on = (select array(select distinct unnest(modules_on || array['svc']::text[]))) where id = b;
  insert into insc_settings (business_id, city_id, rubro, how_presencial, how_linea, how_hibrido, esp) select b, city_id, 'edu', true, true, false, true from businesses where id = b on conflict (business_id) do nothing;
  insert into item_sections (business_id, module, name, sort) values (b, 'svc', '{"es":"Coaching","en":"Coaching"}'::jsonb, 0) returning id into s;
  insert into items (business_id, module, section_id, name, descr, price_cents, duration_min, svc_kind, svc_attrs, deposit_cents, photos, sort) values (b, 'svc', s, '{"es":"Sesión de coaching de carrera","en":"Career coaching session"}'::jsonb, '{"es":"1 hora: currículum, entrevistas y metas.","en":"1 hour: résumé, interviews and goals."}'::jsonb, 6000, 60, 'hora', '{}'::jsonb, 0, '{"https://images.pexels.com/photos/6684167/pexels-photo-6684167.jpeg?auto=compress&cs=tinysrgb&h=600"}'::text[], 0) returning id into it;
  d := (select (now() at time zone ci.timezone)::date + 0 from businesses x join cities ci on ci.id = x.city_id where x.id = b);
  insert into class_groups (business_id, city_id, item_id, label, starts_on, ends_on, dows, start_min, seats_total) select b, city_id, it, jsonb_build_object('es', (array['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'])[extract(dow from d)::int + 1] || ' ' || extract(day from d)::int || ' ' || (array['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'])[extract(month from d)::int] || ' · 3 PM',
                                'en', (array['Sun','Mon','Tue','Wed','Thu','Fri','Sat'])[extract(dow from d)::int + 1] || ' ' || (array['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'])[extract(month from d)::int] || ' ' || extract(day from d)::int || ' · 3 PM'), d, d, '{}'::smallint[], 900, 1 from businesses where id = b;
  d := (select (now() at time zone ci.timezone)::date + 1 from businesses x join cities ci on ci.id = x.city_id where x.id = b);
  insert into class_groups (business_id, city_id, item_id, label, starts_on, ends_on, dows, start_min, seats_total) select b, city_id, it, jsonb_build_object('es', (array['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'])[extract(dow from d)::int + 1] || ' ' || extract(day from d)::int || ' ' || (array['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'])[extract(month from d)::int] || ' · 6 PM',
                                'en', (array['Sun','Mon','Tue','Wed','Thu','Fri','Sat'])[extract(dow from d)::int + 1] || ' ' || (array['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'])[extract(month from d)::int] || ' ' || extract(day from d)::int || ' · 6 PM'), d, d, '{}'::smallint[], 1080, 1 from businesses where id = b;
  d := (select (now() at time zone ci.timezone)::date + 4 from businesses x join cities ci on ci.id = x.city_id where x.id = b);
  d := d + (select min((x - extract(dow from d)::int + 7) % 7) from unnest(array[1]) x);
  insert into class_groups (business_id, city_id, item_id, label, starts_on, ends_on, dows, start_min, seats_total) select b, city_id, it, '{"es":"Lun 5 PM","en":"Mon 5 PM"}'::jsonb, d, d, '{1}'::smallint[], 1020, 1 from businesses where id = b;
  insert into items (business_id, module, section_id, name, descr, price_cents, duration_min, svc_kind, svc_attrs, deposit_cents, photos, sort) values (b, 'svc', s, '{"es":"Taller: habla en público sin miedo","en":"Workshop: public speaking without fear"}'::jsonb, '{"es":"Grupo de 8, martes 7 PM.","en":"Group of 8, Tuesdays 7 PM."}'::jsonb, 2500, 60, 'clase', '{}'::jsonb, 0, '{"https://images.pexels.com/photos/6684167/pexels-photo-6684167.jpeg?auto=compress&cs=tinysrgb&h=600"}'::text[], 1) returning id into it;
  d := (select (now() at time zone ci.timezone)::date + 5 from businesses x join cities ci on ci.id = x.city_id where x.id = b);
  d := d + (select min((x - extract(dow from d)::int + 7) % 7) from unnest(array[2]) x);
  insert into class_groups (business_id, city_id, item_id, label, starts_on, ends_on, dows, start_min, seats_total) select b, city_id, it, '{"es":"Martes 7 PM","en":"Tuesday 7 PM"}'::jsonb, d, d, '{2}'::smallint[], 1140, 8 from businesses where id = b;
end $$;
